(() => {
  'use strict';
  const CRC_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
      t[n] = c >>> 0;
    }
    return t;
  })();
  const crc32 = (u8) => {
    let c = 0xffffffff;
    for (let i = 0; i < u8.length; i++) c = CRC_TABLE[(c ^ u8[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
  const enc = new TextEncoder();
  const dec = new TextDecoder('utf-8');
  const transform = async (u8, stream) => new Uint8Array(await new Response(new Blob([u8]).stream().pipeThrough(stream)).arrayBuffer());
  const deflateRaw = (u8) => transform(u8, new CompressionStream('deflate-raw'));
  const inflateRaw = (u8) => transform(u8, new DecompressionStream('deflate-raw'));

  class JSZip {
    constructor() { this._entries = new Map(); this.files = {}; }
    file(name, data) {
      const clean = String(name).replace(/^\/+/, '');
      const u8 = typeof data === 'string' ? enc.encode(data) : data instanceof Uint8Array ? data : new Uint8Array(data);
      this._entries.set(clean, u8);
      this.files[clean] = { dir: false, async: async (type) => (type === 'string' ? dec.decode(u8) : u8.slice()) };
      return this;
    }
    async generateAsync({ type = 'uint8array', compression = 'STORE' } = {}) {
      const d = new Date();
      const time = (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1);
      const date = ((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate();
      const parts = [], central = [];
      let offset = 0;
      const compress = String(compression).toUpperCase() === 'DEFLATE';
      for (const [name, raw] of this._entries.entries()) {
        const nb = enc.encode(name), crc = crc32(raw);
        let body = raw, method = 0;
        if (compress && raw.length > 64 && typeof CompressionStream !== 'undefined') {
          const def = await deflateRaw(raw);
          if (def.length < raw.length) { body = def; method = 8; }
        }
        const lh = new DataView(new ArrayBuffer(30));
        lh.setUint32(0, 0x04034b50, true); lh.setUint16(4, 20, true); lh.setUint16(6, 0x0800, true);
        lh.setUint16(8, method, true); lh.setUint16(10, time, true); lh.setUint16(12, date, true);
        lh.setUint32(14, crc, true); lh.setUint32(18, body.length, true); lh.setUint32(22, raw.length, true);
        lh.setUint16(26, nb.length, true);
        parts.push(new Uint8Array(lh.buffer), nb, body);
        const ch = new DataView(new ArrayBuffer(46));
        ch.setUint32(0, 0x02014b50, true); ch.setUint16(4, 20, true); ch.setUint16(6, 20, true); ch.setUint16(8, 0x0800, true);
        ch.setUint16(10, method, true); ch.setUint16(12, time, true); ch.setUint16(14, date, true);
        ch.setUint32(16, crc, true); ch.setUint32(20, body.length, true); ch.setUint32(24, raw.length, true);
        ch.setUint16(28, nb.length, true); ch.setUint32(42, offset, true);
        central.push(new Uint8Array(ch.buffer), nb);
        offset += 30 + nb.length + body.length;
      }
      const cdSize = central.reduce((a, p) => a + p.length, 0);
      const end = new DataView(new ArrayBuffer(22));
      end.setUint32(0, 0x06054b50, true); end.setUint16(8, this._entries.size, true); end.setUint16(10, this._entries.size, true);
      end.setUint32(12, cdSize, true); end.setUint32(16, offset, true);
      const all = [...parts, ...central, new Uint8Array(end.buffer)];
      const out = new Uint8Array(all.reduce((a, p) => a + p.length, 0));
      let pos = 0;
      for (const p of all) { out.set(p, pos); pos += p.length; }
      if (type === 'blob') return new Blob([out], { type: 'application/zip' });
      return out;
    }
    static async loadAsync(input) {
      const u8 = input instanceof Uint8Array ? input : new Uint8Array(input);
      const dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
      let eocd = -1;
      for (let i = u8.length - 22; i >= Math.max(0, u8.length - 65557); i--) {
        if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
      }
      if (eocd < 0) throw new Error('ZIP không hợp lệ');
      const count = dv.getUint16(eocd + 10, true);
      let p = dv.getUint32(eocd + 16, true);
      const z = new JSZip();
      for (let n = 0; n < count; n++) {
        if (p + 46 > u8.length || dv.getUint32(p, true) !== 0x02014b50) throw new Error('ZIP bị hỏng');
        const flags = dv.getUint16(p + 8, true), method = dv.getUint16(p + 10, true);
        const csize = dv.getUint32(p + 20, true), nameLen = dv.getUint16(p + 28, true);
        const extraLen = dv.getUint16(p + 30, true), commentLen = dv.getUint16(p + 32, true);
        const lho = dv.getUint32(p + 42, true);
        if (p + 46 + nameLen > u8.length) throw new Error('ZIP bị hỏng');
        const name = (flags & 0x0800 ? dec : new TextDecoder('latin1')).decode(u8.subarray(p + 46, p + 46 + nameLen));
        p += 46 + nameLen + extraLen + commentLen;
        if (name.endsWith('/')) { z.files[name] = { dir: true }; continue; }
        if (lho + 30 > u8.length || dv.getUint32(lho, true) !== 0x04034b50) throw new Error('ZIP bị hỏng');
        const start = lho + 30 + dv.getUint16(lho + 26, true) + dv.getUint16(lho + 28, true);
        if (start + csize > u8.length) throw new Error('ZIP bị hỏng');
        const slice = u8.subarray(start, start + csize);
        const bytes = method === 0 ? slice.slice() : method === 8 ? await inflateRaw(slice) : (() => { throw new Error(`ZIP method ${method}`); })();
        z.file(name, bytes);
      }
      return z;
    }
  }
  globalThis.JSZip = JSZip;
})();
